    input start_chan2,
    input [7:0] src_addr1,
    input [7:0] dst_addr1,
    input [7:0] src_addr2,
    input [7:0] dst_addr2,
    output reg done_chan1,
    output reg done_chan2
);
    reg [3:0] state;
    reg [7:0] data1, data2;
    parameter IDLE = 4'b0000, TRANSFER1 = 4'b0001, TRANSFER2 = 4'b0010, DONE1 = 4'b0011, DONE2 = 4'b0100;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state <= IDLE;
            done_chan1 <= 0;
            done_chan2 <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (enable_chan1 && start_chan1) begin
                        state <= TRANSFER1;
                    end else if (enable_chan2 && start_chan2) begin
                        state <= TRANSFER2;
                    end
                end
                TRANSFER1: begin
                    // Simulate data transfer for channel 1
                    data1 <= src_addr1;  // Dummy read
                    done_chan1 <= 1;
                    state <= DONE1;
                end
                TRANSFER2: begin
                    // Simulate data transfer for channel 2
                    data2 <= src_addr2;  // Dummy read
                    done_chan2 <= 1;
                    state <= DONE2;
                end
                DONE1: begin
                    // Transfer complete for channel 1
                    state <= IDLE;
                end
                DONE2: begin
                    // Transfer complete for channel 2
                    state <= IDLE;
                end
            endcase
        end
    end
endmodule

