module sram_cell (  
    input wire data_in,  
    input wire write_enable,  
    input wire read_enable,  
    output reg data_out  
);  
    reg stored_data;  

    always @(posedge write_enable or posedge read_enable) begin  
        if (write_enable) begin  
            stored_data <= data_in;  
        end  
        if (read_enable) begin  
            data_out <= stored_data;  
        end  
    end  
endmodule

module watchdog_timer(
    input clk,
    input reset,
    output reg timeout,
    output reg [7:0] count
);
    parameter TIMEOUT_LIMIT = 8'd10; // Example timeout limit

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            count <= 8'd0;
            timeout <= 1'b0;
        end else if (count < TIMEOUT_LIMIT) begin
            count <= count + 1;
            timeout <= 1'b0;
        end else begin
            timeout <= 1'b1;
        end
    end
endmodule

