module adaptive_lms_filter #(
    parameter N = 5, // Number of taps
    parameter STEP_SIZE = 8'h01 // Step size for adaptation
)(
    input clk,
    input rst,
    input signed [15:0] x, // Input signal
    input signed [15:0] d, // Desired output signal
    output reg signed [15:0] y // Filter output
);

reg signed [15:0] w [0:N-1]; // Weights
reg signed [15:0] x_delay [0:N-1]; // Delays for x

integer i;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        y <= 16'b0;
        // Initialize weights to zero
        for (i = 0; i < N; i = i + 1) begin
            w[i] <= 16'b0;
        end
    end else begin
        // Shift input samples
        x_delay[0] <= x;
        for (i = 1; i < N; i = i + 1) begin
            x_delay[i] <= x_delay[i-1];
        end

        // Calculate filter output
        y <= 16'b0;
        for (i = 0; i < N; i = i + 1) begin
            y <= y + (w[i] * x_delay[i]);
        end

        // Weight update
        for (i = 0; i < N; i = i + 1) begin
            w[i] <= w[i] + (STEP_SIZE * (d - y) * x_delay[i]);
        end
    end
end
endmodule

