module counter_16bit (
    input wire clk,
    input wire reset,
    input wire up,
    output reg [15:0] count
);
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            count <= 16'b0;
        end else if (up) begin
            count <= count + 1;
        end else begin
            count <= count - 1;
