module fractional_n_pll(  
    input wire clk,  
    input wire reset,  
    input wire [3:0] integer_part,  
    input wire [3:0] fractional_part,  
    output reg frequency_out  
);  
    reg [7:0] freq_value;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            frequency_out <= 0;  
            freq_value <= 0;  
        end else begin  
            freq_value <= integer_part + (fractional_part / 16);  
            frequency_out <= freq_value;  
        end  
    end  
endmodule

