module backpropagation (
    input wire clk,
    input wire reset,
    input wire [15:0] x1,   // First input
    input wire [15:0] x2,   // Second input
    input wire [15:0] target, // Expected output
    input wire [15:0] learning_rate, // Learning rate
    output reg [15:0] w1,   // Weight for x1
    output reg [15:0] w2    // Weight for x2
);
    reg [15:0] output_neuron;
    reg [15:0] error;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            w1 <= 16'b0;
            w2 <= 16'b0;
        end else begin
            output_neuron <= (w1 * x1 + w2 * x2);
            error <= target - output_neuron;
            w1 <= w1 + (learning_rate * error * x1);
            w2 <= w2 + (learning_rate * error * x2);
        end
    end
endmodule

