module watchdog_timer #(parameter TIMEOUT = 100)  
(  
    input wire clk,  
    input wire rst,  
    input wire enable,  
    output reg timeout  
);  
    reg [6:0] counter; // 7-bit counter to count up to 100  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            counter <= 0;  
            timeout <= 0;  
        end else if (enable) begin  
            if (counter < TIMEOUT) begin  
                counter <= counter + 1;  
                timeout <= 0;  
            end else begin  
                timeout <= 1;  
            end  
        end else begin  
            counter <= 0;  
            timeout <= 0;  
        end  
    end  
endmodule

