module PISO_Shift_Register (  
    input wire clk,  
    input wire load,  
    input wire [7:0] data_in,  
    output reg serial_out  
);  
    reg [7:0] shift_reg;  

    always @(posedge clk) begin  
        if (load) begin  
            shift_reg <= data_in;  
        end else begin  
            serial_out <= shift_reg[7];  
            shift_reg <= {shift_reg[6:0], 1'b0};  
        end  
    end  
