module spi_controller(
    input wire clk,
    input wire start,
    input wire [7:0] data_in,
    output reg MOSI,
    output reg SCK,
    output reg done
);
    reg [2:0] bit_count;
    reg [7:0] shift_reg;

    always @(posedge clk) begin
        if (start) begin
            shift_reg <= data_in;
            bit_count <= 3'b000;
            done <= 1'b0;
            SCK <= 1'b0;
        end else if (bit_count < 8) begin
            SCK <= ~SCK; // Toggle clock
            if (SCK) begin
                MOSI <= shift_reg[7]; // Send the MSB first
                shift_reg <= {shift_reg[6:0], 1'b0}; // Shift left
                bit_count <= bit_count + 1;
            end
        end else begin
            done <= 1'b1; // Indicate done
        end
    end
endmodule

