module viterbi_decoder (
    input wire clk,
    input wire rst,
    input wire [1:0] encoded_data,
    input wire valid,
    output reg [1:0] decoded_data,
    output reg valid_out
);
    reg [2:0] state;
    reg [2:0] next_state;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state <= 3'b000;
            decoded_data <= 2'b00;
            valid_out <= 0;
        end else if (valid) begin
            state <= next_state;
            // Decoding logic (simplified version)
            decoded_data <= encoded_data ^ state[1:0]; // Example operation
            valid_out <= 1;
        end
    end

    always @* begin
        case (state)
            3'b000: next_state = (valid) ? 3'b001 : state;
            3'b001: next_state = (valid) ? 3'b010 : state;
            3'b010: next_state = (valid) ? 3'b011 : state;
            3'b011: next_state = (valid) ? 3'b000 : state;
            default: next_state = state;
        endcase
    end
endmodule

