module fractional_n_pll #(parameter N=4, M=2) (  
    input clk_ref,  
    input reset,  
    input [3:0] fractional_divider,  
    output reg clk_out  
);  

    reg [N-1:0] count;  
    reg [N-1:0] vco_count;  

    always @(posedge clk_ref or posedge reset) begin  
        if (reset) begin  
            count <= 0;  
            vco_count <= 0;  
            clk_out <= 0;  
        end else begin  
            count <= count + 1;  
            if (count == fractional_divider) begin  
                clk_out <= ~clk_out;  
                count <= 0;  
            end  
            vco_count <= vco_count + 1;  
        end  
    end  
endmodule

