module nvme_command_processor (
    input clk,
    input reset,
    input [2:0] command, // 3-bit command input
    output reg [1:0] status // 2-bit status output
);

    // Command definitions
    localparam READ = 3'b000;
    localparam WRITE = 3'b001;
    localparam FLUSH = 3'b010;
    localparam DELETE = 3'b011;
    localparam GET_STATUS = 3'b100;

    // Status definitions
    localparam IDLE = 2'b00;
    localparam SUCCESS = 2'b01;
    localparam ERROR = 2'b10;

    // State machine
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            status <= IDLE;
        end else begin
            case (command)
                READ: status <= SUCCESS;
                WRITE: status <= SUCCESS;
                FLUSH: status <= SUCCESS;
                DELETE: status <= SUCCESS;
                GET_STATUS: status <= SUCCESS;
                default: status <= ERROR;
            endcase
        end
    end
endmodule

