        count <= 2'b00;  
    else  
        count <= count + 1;  
end  

endmodule

module matrix_inverse (
    input [15:0] matrix, // 4 elements (4x4 bits for 2x2 matrix)
    output reg [15:0] inv_matrix // 4 elements (4x4 bits for inverted matrix)
);
    wire signed [15:0] a = matrix[15:12];
    wire signed [15:0] b = matrix[11:8];
    wire signed [15:0] c = matrix[7:4];
    wire signed [15:0] d = matrix[3:0];

    wire signed [15:0] det = a * d - b * c; // Determinant

    always @(*) begin
        if (det != 0) begin
            inv_matrix[15:12] = d / det;      // inv(1,1)
            inv_matrix[11:8]  = -b / det;     // inv(1,2)
            inv_matrix[7:4]   = -c / det;     // inv(2,1)
            inv_matrix[3:0]   = a / det;      // inv(2,2)
        end else begin
            inv_matrix = 16'bx; // Undefined if determinant is zero
        end
    end
endmodule

module NAT_Translator(  
    input clk,  
    input reset,  
    input [4:0] internal_ip,  
    output reg [4:0] external_ip  
);  
    reg [1:0] state;  

    // State encoding  
    localparam IDLE = 2'b00,  
               TRANSLATE = 2'b01;  

    // Internal mapping of IP addresses (for example purposes)  
    reg [4:0] mapped_externals[0:31];  

    initial begin  
        // Sample mapping for demonstration  
        mapped_externals[5] = 5'b00001; // internal 5 -> external 1  
        mapped_externals[10] = 5'b00010; // internal 10 -> external 2  
        mapped_externals[20] = 5'b00011; // internal 20 -> external 3  
        mapped_externals[25] = 5'b00100; // internal 25 -> external 4  
        mapped_externals[30] = 5'b00101; // internal 30 -> external 5  
    end  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            state <= IDLE;  
            external_ip <= 5'b00000;  
        end else begin  
            case (state)  
                IDLE: begin  
                    if (internal_ip != 5'b00000) begin  
                        state <= TRANSLATE;  
                    end  
                end  
                TRANSLATE: begin  
                    external_ip <= mapped_externals[internal_ip];  
                    state <= IDLE;  
                end  
            endcase  
        end  
    end  
endmodule

module comparator_32bit (  
    input [31:0] A,  
    input [31:0] B,  
    output reg equal  
);  
    always @(*) begin  
        if (A == B)  
            equal = 1'b1;  
        else  
            equal = 1'b0;  
    end  
endmodule

module serializer_32bit (  
    input wire clk,  
    input wire rst,  
    input wire [31:0] data_in,  
    output reg data_out  
);  
    reg [4:0] count; // 5 bits to count from 0 to 31  
    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            count <= 0;  
            data_out <= 0;  
        end else if (count < 32) begin  
            data_out <= data_in[count];  
            count <= count + 1;  
        end else begin  
            data_out <= 0; // No more data to send  
        end  
    end  
endmodule

module PISO #(parameter WIDTH = 8) (  
    input wire clk,  
    input wire reset,  
    input wire load,  
    input wire [WIDTH-1:0] parallel_in,  
    output reg serial_out  
);  
    reg [WIDTH-1:0] shift_reg;  
    integer count;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            shift_reg <= 0;  
            serial_out <= 0;  
            count <= 0;  
        end else if (load) begin  
            shift_reg <= parallel_in;  
            count <= WIDTH - 1;  
        end else if (count >= 0) begin  
            serial_out <= shift_reg[count];  
            count <= count - 1;  
        end  
    end  
endmodule

module dac_24_to_8 (  
