endmodule

module fir_filter (
    input wire clk,
    input wire rst,
    input wire [3:0] x,
    output reg [3:0] y
);
    reg [3:0] buffer [0:3];
    integer i;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            y <= 4'b0;
            for (i = 0; i < 4; i = i + 1) begin
                buffer[i] <= 4'b0;
            end
        end else begin
            buffer[0] <= x;
            buffer[1] <= buffer[0];
            buffer[2] <= buffer[1];
            buffer[3] <= buffer[2];
            y <= buffer[0] + buffer[1] + buffer[2] + buffer[3];
        end
    end
endmodule

module chebyshev_filter(input [1:0] coeff,  
                        input x_in,  
                        output reg y_out);  

    always @(*) begin  
        case(coeff)  
            2'b00: y_out = x_in;  
            2'b01: y_out = (x_in & 1'b1) ^ (x_in & 1'b0);  
            2'b10: y_out = (x_in & 1'b1) ^ ((x_in & 1'b1) >> 1);  
            2'b11: y_out = (x_in & 1'b1) ^ (x_in & 1'b1);  
            default: y_out = 1'b0;  
        endcase  
    end  
endmodule

