module kalman_filter(
    input clk,
    input rst,
    input [15:0] measurement,
    input [15:0] estimate,
    input [15:0] process_noise,
    input [15:0] measurement_noise,
    output reg [15:0] updated_estimate
);

reg [15:0] kalman_gain;
reg [15:0] temp_estimate;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        updated_estimate <= 16'b0;
    end else begin
        // Compute Kalman Gain
        kalman_gain <= process_noise / (process_noise + measurement_noise);

        // Update estimate
        temp_estimate <= estimate + kalman_gain * (measurement - estimate);
        updated_estimate <= temp_estimate;
    end
end

endmodule

