module pipeline_processor (
    input clk,
    input reset,
    input [4:0] instruction_in,
    output reg [4:0] instruction_out
);
    reg [4:0] stage [0:6]; // 7 stages of the pipeline

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            instruction_out <= 5'b0;
            stage[0] <= 5'b0;
            stage[1] <= 5'b0;
            stage[2] <= 5'b0;
            stage[3] <= 5'b0;
            stage[4] <= 5'b0;
            stage[5] <= 5'b0;
            stage[6] <= 5'b0;
        end else begin
            stage[0] <= instruction_in; // Fetch
            stage[1] <= stage[0];       // Decode
            stage[2] <= stage[1];       // Execute
            stage[3] <= stage[2];       // Memory Access
            stage[4] <= stage[3];       // Write Back
            stage[5] <= stage[4];       // Additional Stage 1
            stage[6] <= stage[5];       // Additional Stage 2
            instruction_out <= stage[6]; // Output
        end
    end
endmodule

module butterworth_filter (  
    input clk,  // Clock signal  
    input rst,  // Reset signal  
    input signed [15:0] x_in,  // Input sample  
    output reg signed [15:0] y_out  // Filtered output  
);  
    reg signed [15:0] x_mem [0:1];  // Memory for input samples  
    reg signed [15:0] y_mem [0:1];  // Memory for output samples  
    integer i;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            // Reset all registers  
            for (i = 0; i < 2; i = i + 1) begin  
                x_mem[i] <= 0;  
                y_mem[i] <= 0;  
            end  
            y_out <= 0;  
        end else begin  
            // Shift input samples  
            x_mem[1] <= x_mem[0];  
            x_mem[0] <= x_in;  

            // Perform Butterworth filter operation (simplified)  
            y_mem[1] <= y_mem[0];  
            y_mem[0] <= (x_mem[0] + 2*x_mem[1] + y_mem[1]) >> 2;  

            // Output the filtered signal  
            y_out <= y_mem[0];  
        end  
    end  
endmodule

