module audio_frame_rate_converter(  
    input clk,  
    input reset,  
    input [15:0] audio_in,  
    output reg [15:0] audio_out  
);  
    reg [1:0] state;  
    reg [15:0] sample_buffer;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            state <= 0;  
            audio_out <= 0;  
            sample_buffer <= 0;  
        end else begin  
            case (state)  
                0: begin  
                    sample_buffer <= audio_in;  
                    state <= 1;  
                end  
                1: begin  
                    audio_out <= sample_buffer;  
                    state <= 0;  
                end  
            endcase  
        end  
    end  
endmodule

