module watchdog_timer (
    input wire clk,
    input wire rst,
    input wire kick,
    input wire [2:0] timeout,
    output reg reset_signal
);
    reg [2:0] counter;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            counter <= 3'b000;
            reset_signal <= 1'b0;
        end else if (kick) begin
            counter <= 3'b000;
            reset_signal <= 1'b0;
        end else if (counter < timeout) begin
            counter <= counter + 1;
            reset_signal <= 1'b0;
        end else begin
            reset_signal <= 1'b1;
        end
    end
endmodule

module butterworth_filter (
    input clk,
    input reset,
    input [3:0] signal_in,
    output reg [3:0] signal_out
);
    reg [3:0] prev_signal;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            signal_out <= 4'b0000;
            prev_signal <= 4'b0000;
        end else begin
            signal_out <= (signal_in + prev_signal) >> 1; // Simple averaging filter
            prev_signal <= signal_in;
        end
    end
endmodule

module tcp_segment_type(input [15:0] segment_size, output reg [1:0] segment_type);  
    always @(*) begin  
        if (segment_size <= 16'd512)  
            segment_type = 2'b00;  
        else if (segment_size <= 16'd1024)  
            segment_type = 2'b01;  
        else if (segment_size <= 16'd1500)  
            segment_type = 2'b10;  
        else  
            segment_type = 2'b11;  
    end  
endmodule

module deserializer(
    input wire clk,
    input wire reset,
    input wire [31:0] data_in,
    output reg serial_out,
    output reg valid
);
    reg [4:0] bit_count;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            bit_count <= 5'b0;
            serial_out <= 1'b0;
            valid <= 1'b0;
        end else begin
            if (bit_count < 32) begin
                serial_out <= data_in[31 - bit_count];
                valid <= 1'b1;
                bit_count <= bit_count + 1;
            end else begin
                valid <= 1'b0; // No valid data after 32 bits
            end
        end
    end
endmodule

module phase_detector (
    input clk1,
    input clk2,
    input rst,
    output reg phase_out
);
    reg last_clk1;
    reg last_clk2;

    always @(posedge clk1 or posedge rst) begin
        if (rst) begin
            phase_out <= 0;
            last_clk1 <= 0;
            last_clk2 <= 0;
        end else begin
            last_clk1 <= 1;
            if (last_clk2 == 0) begin
                phase_out <= 1;  // clk1 leads clk2
            end
        end
    end

    always @(posedge clk2 or posedge rst) begin
        if (rst) begin
            phase_out <= 0;
            last_clk1 <= 0;
            last_clk2 <= 0;
        end else begin
            last_clk2 <= 1;
            if (last_clk1 == 0) begin
                phase_out <= 0;  // clk2 leads clk1
            end
        end
    end

    always @(negedge clk1 or negedge clk2 or posedge rst) begin
        if (rst) begin
            phase_out <= 0;
        end else begin
            if (last_clk1 == 1 && last_clk2 == 1) begin
                phase_out <= phase_out; // no change
            end
        end
    end
endmodule

module pipeline_processor (
    input clk,
    input rst,
    input [4:0] instruction_in,
    output reg [4:0] instruction_out
);

reg [4:0] stage [0:6];

always @(posedge clk or posedge rst) begin
    if (rst) begin
        instruction_out <= 5'b0;
        stage[0] <= 5'b0;
        stage[1] <= 5'b0;
        stage[2] <= 5'b0;
        stage[3] <= 5'b0;
        stage[4] <= 5'b0;
        stage[5] <= 5'b0;
        stage[6] <= 5'b0;
    end else begin
        stage[0] <= instruction_in & 5'b11111; // Stage 0
        stage[1] <= stage[0] & 5'b10101; // Stage 1
        stage[2] <= stage[1] & 5'b11011; // Stage 2
        stage[3] <= stage[2] & 5'b11100; // Stage 3
        stage[4] <= stage[3] & 5'b10001; // Stage 4
        stage[5] <= stage[4] & 5'b01111; // Stage 5
        stage[6] <= stage[5]; // Stage 6
        instruction_out <= stage[6]; // Output
    end
end

endmodule

module eeprom_cell (  
    input wire clk,  
    input wire write_enable,  
    input wire erase,  
    input wire data_in,  
    output reg data_out  
);  
    reg stored_data;  

    always @(posedge clk) begin  
        if (erase) begin  
            stored_data <= 0;  
        end else if (write_enable) begin  
            stored_data <= data_in;  
        end  
    end  

    always @(posedge clk) begin  
        data_out <= stored_data;  
    end  
endmodule

