module FractionalNPLL (
    input wire clk_ref,
    input wire [3:0] frac_value,
    input wire rst,
    output reg clk_out
);
    reg [15:0] counter;
    reg [15:0] div_count;
    reg [3:0] frac_num;

    always @(posedge clk_ref or posedge rst) begin
        if (rst) begin
            counter <= 0;
            clk_out <= 0;
            div_count <= 0;
            frac_num <= 0;
        end else begin
            counter <= counter + 1;
            if (counter >= (16 + frac_value)) begin
                clk_out <= ~clk_out;
                counter <= 0;
            end
            div_count <= div_count + 1;
            if (div_count >= (16 + frac_value)) begin
                div_count <= 0;
                frac_num <= frac_value;
            end
        end
    end
endmodule

module eight_bit_adder (
    input [7:0] a,
    input [7:0] b,
    output [7:0] sum,
    output carry_out
);
    wire [8:0] full_sum;

    assign full_sum = {1'b0, a} + {1'b0, b};
    assign sum = full_sum[7:0];
    assign carry_out = full_sum[8];
endmodule

