module fifo_queue #(parameter DEPTH = 4, WIDTH = 8) (
    input wire clk,
    input wire rst,
    input wire enq,
    input wire deq,
    input wire [WIDTH-1:0] data_in,
    output reg [WIDTH-1:0] data_out,
    output reg full,
    output reg empty
);
    reg [WIDTH-1:0] mem [0:DEPTH-1];
    reg [3:0] head;
    reg [3:0] tail;
    reg [3:0] count;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            head <= 0;
            tail <= 0;
            count <= 0;
            full <= 0;
            empty <= 1;
        end else begin
            if (enq && !full) begin
                mem[head] <= data_in;
                head <= (head + 1) % DEPTH;
                count <= count + 1;
            end
            if (deq && !empty) begin
                data_out <= mem[tail];
                tail <= (tail + 1) % DEPTH;
                count <= count - 1;
            end
            full <= (count == DEPTH);
            empty <= (count == 0);
        end
    end
endmodule

