    reg clk;
    reg request_alloc;
    reg [3:0] request_size;
    reg rst;
    wire [3:0] allocated_size;
    wire success;

    // Test tracking
    integer test_num;
    integer pass_count;
    integer fail_count;

    // Instantiate the DUT (Device Under Test)
    memory_allocator dut (
        .clk(clk),
        .request_alloc(request_alloc),
        .request_size(request_size),
        .rst(rst),
        .allocated_size(allocated_size),
        .success(success)
    );

    // Clock generation (10ns period)
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

        task reset_dut;

        begin
            rst = 1;
            request_alloc = 0;
            request_size = 0;
            repeat(2) @(posedge clk);
            #1 rst = 0;
            @(posedge clk);
        end
        endtask
    task testcase001;

        begin
            test_num = test_num + 1;
            $display("Test Case %03d: Basic Allocation (Size 4)", test_num);
            reset_dut();
            request_alloc = 1;
            request_size = 4;
            @(posedge clk);
            #1;
            #1;

            check_outputs(4, 1);
        end
        endtask

    task testcase002;

        begin
            test_num = test_num + 1;
            $display("Test Case %03d: Large Allocation (Size 15)", test_num);
            reset_dut();
            request_alloc = 1;
            request_size = 15;
            @(posedge clk);
            #1;
            #1;

            check_outputs(15, 1);
        end
        endtask

    task testcase003;

        begin
            test_num = test_num + 1;
            $display("Test Case %03d: Multiple Allocations (Accumulation)", test_num);
            reset_dut();

            request_alloc = 1; request_size = 4;
            @(posedge clk);
            #2 request_alloc = 0;
            @(posedge clk);

            request_alloc = 1; request_size = 4;
            @(posedge clk);
            #1;

            #1;


            check_outputs(4, 1);
        end
        endtask

    task testcase004;

        begin
            test_num = test_num + 1;
            $display("Test Case %03d: Allocation Failure (Out of Memory)", test_num);
            reset_dut();

            request_alloc = 1; request_size = 12;
            @(posedge clk);
            #2 request_alloc = 0;
            @(posedge clk);

            request_alloc = 1; request_size = 8;
            @(posedge clk);
            #1;

            #1;


            check_outputs(0, 0);
        end
        endtask

    task testcase005;

        begin
            test_num = test_num + 1;
            $display("Test Case %03d: Zero Size Request", test_num);
            reset_dut();
            request_alloc = 1;
            request_size = 0;
            @(posedge clk);
            #1;

            #1;


            check_outputs(0, 0);
        end
        endtask

    task testcase006;

        begin
            test_num = test_num + 1;
            $display("Test Case %03d: Memory Clear after Reset", test_num);
            reset_dut();

            request_alloc = 1; request_size = 15;
            @(posedge clk);
            #2 request_alloc = 0;
            @(posedge clk);

            reset_dut();

            request_alloc = 1; request_size = 15;
            @(posedge clk);
            #1;
            #1;

            check_outputs(15, 1);
        end
        endtask

    // Test stimulus
    initial begin
        // Initialize
        test_num = 0;
        pass_count = 0;
        fail_count = 0;

        $display("========================================");
        $display("memory_allocator Testbench");
        $display("========================================");


        testcase001();
        testcase002();
        testcase003();
        testcase004();
        testcase005();
        testcase006();


// Print summary
        $display("\n========================================");
        $display("Test Summary");
        $display("========================================");
        $display("Tests Passed: %0d", pass_count);
        $display("Tests Failed: %0d", fail_count);
        $display("Total Tests:  %0d", pass_count + fail_count);
        $display("========================================");

        if (fail_count == 0)
            $display("ALL TESTS PASSED!");
        else
            $display("SOME TESTS FAILED!");

        $display("\nSimulation completed at time %0t", $time);
        $finish;
    end

    // Task to check outputs
    task check_outputs;
        input [3:0] expected_allocated_size;
        input expected_success;
        begin
            if (expected_allocated_size === (expected_allocated_size ^ allocated_size ^ expected_allocated_size) &&
                expected_success === (expected_success ^ success ^ expected_success)) begin
                $display("PASS");
                $display("  Outputs: allocated_size=%h, success=%b",
                         allocated_size, success);
                pass_count = pass_count + 1;
            end else begin
                $display("FAIL");
                $display("  Expected: allocated_size=%h, success=%b",
                         expected_allocated_size, expected_success);
                $display("  Got:      allocated_size=%h, success=%b",
                         allocated_size, success);
                fail_count = fail_count + 1;
            end
        end
    endtask

    // Timeout watchdog
    initial begin
        #1000000; // 1ms timeout
        $display("\nERROR: Simulation timeout!");
        $finish;
    end

    // Optional: Waveform dump for debugging
    initial begin
        $dumpfile("wave.vcd");
        $dumpvars(0,clk, request_alloc, request_size, rst, allocated_size, success);
    end

endmodule

