module sd_card_controller (
    input wire clk,
    input wire reset,
    input wire [7:0] data_in,
    output reg data_ready,
    output reg [7:0] data_out
);
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            data_ready <= 0;
            data_out <= 8'b0;
        end else begin
            data_out <= data_in;
            data_ready <= 1;
        end
    end
endmodule

